// Package lockfile reads GitHub Actions workflow dependency lockfiles.
// https://docs.github.com/en/enterprise-cloud@latest/actions/concepts/security/workflow-dependency-lockfiles
package lockfile

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"

	parserlock "github.com/github/actions-lockfile/go/pkg/lockfile"
)

// Path is the path of the lockfile from the repository root.
const Path = parserlock.Path

// Lockfile is a workflow dependency lockfile generated by `gh actions-lock`.
type Lockfile struct {
	file parserlock.File
}

// Read reads and validates the lockfile for the workflows.
// Required fields are validated only for entries those workflows reference,
// so a broken entry that no workflow uses doesn't make the whole lockfile unreadable.
// It returns nil without an error if the lockfile doesn't exist or no workflow is given.
func Read(workflowFilePaths []string) (*Lockfile, error) {
	if len(workflowFilePaths) == 0 {
		// The parser validates all entries if no workflow file path is given.
		return nil, nil //nolint:nilnil
	}
	b, err := os.ReadFile(Path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil //nolint:nilnil
		}
		return nil, fmt.Errorf("read a lockfile: %w", err)
	}
	return Parse(b, workflowFilePaths...)
}

// Parse parses and validates the content of a lockfile.
// If workflowFilePaths are given, required fields are validated only for entries those workflows reference.
// Otherwise, all entries are validated.
func Parse(b []byte, workflowFilePaths ...string) (*Lockfile, error) {
	paths := make([]string, len(workflowFilePaths))
	for i, p := range workflowFilePaths {
		paths[i] = filepath.ToSlash(p)
	}
	f, err := parserlock.Parse(b, paths...)
	if err != nil {
		return nil, fmt.Errorf("parse a lockfile: %w", err)
	}
	return &Lockfile{file: f}, nil
}

// Lockable reports whether uses is a repository action, which the lockfile can lock.
// Local actions, Docker images, and reusable workflows aren't.
func Lockable(uses string) bool {
	return parserlock.ParseActionRef(uses) != nil
}

// Locked reports whether the action uses is locked for the workflow.
// It returns false if lf is nil or uses isn't a repository action, such as a local action, a Docker image, or a reusable workflow.
// The lockfile records actions as canonical keys `owner/repo@ref`, where owner and repo are lowercased and a sub-action path is dropped.
func (lf *Lockfile) Locked(workflowFilePath, uses string) bool {
	_, ok := lf.lookup(workflowFilePath, uses)
	return ok
}

// Commit returns the commit SHA-1 the action uses is locked to for the workflow.
// It returns false if the action isn't locked for the workflow, as Locked does,
// or the commit isn't a SHA-1 digest.
func (lf *Lockfile) Commit(workflowFilePath, uses string) (string, bool) {
	dep, ok := lf.lookup(workflowFilePath, uses)
	if !ok {
		return "", false
	}
	// The commit is an algo-prefixed digest such as sha1-<hex>.
	sha, ok := strings.CutPrefix(dep.Commit, "sha1-")
	if !ok {
		return "", false
	}
	return strings.ToLower(sha), true
}

func (lf *Lockfile) lookup(workflowFilePath, uses string) (parserlock.Action, bool) {
	if lf == nil {
		return parserlock.Action{}, false
	}
	ref := parserlock.ParseActionRef(uses)
	if ref == nil {
		return parserlock.Action{}, false
	}
	key := parserlock.IndexKey(ref.Owner, ref.Repo, ref.Ref)
	keys, ok := lf.file.LookupWorkflow(filepath.ToSlash(workflowFilePath))
	if !ok || !slices.Contains(keys, key) {
		return parserlock.Action{}, false
	}
	dep, ok := lf.file.Dependencies[key]
	return dep, ok
}
